911	    <script>
912	        document.addEventListener('DOMContentLoaded', function() {
913	            document.getElementById('year').textContent = new Date().getFullYear();
914	
915	            const menuToggle = document.querySelector('.menu-toggle');
916	            const navMenu = document.getElementById('nav-menu');
917	
918	            if (menuToggle) {
919	                const isDesktop = () => window.innerWidth > 768;
920	
921	                const updateMenuVisibility = () => {
922	                    if (isDesktop()) {
923	                        navMenu.removeAttribute('hidden');
924	                        menuToggle.setAttribute('aria-expanded', 'true');
925	                    } else {
926	                        navMenu.setAttribute('hidden', '');
927	                        menuToggle.setAttribute('aria-expanded', 'false');
928	                    }
929	                };
930	
931	                const closeMenu = () => {
932	                    if (!isDesktop()) {
933	                        menuToggle.setAttribute('aria-expanded', 'false');
934	                        navMenu.setAttribute('hidden', '');
935	                        menuToggle.focus();
936	                    }
937	                };
938	
939	                updateMenuVisibility();
940	                window.addEventListener('resize', updateMenuVisibility);
941	
942	                menuToggle.addEventListener('click', function() {
943	                    if (!isDesktop()) {
944	                        const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
945	                        menuToggle.setAttribute('aria-expanded', !isExpanded);
946	                        navMenu.toggleAttribute('hidden');
947	                    }
948	                });
949	
950	                document.addEventListener('keydown', (e) => {
951	                    if (e.key === 'Escape' && menuToggle.getAttribute('aria-expanded') === 'true') {
952	                        closeMenu();
953	                    }
954	                });
955	
956	                const navLinks = navMenu.querySelectorAll('a');
957	                navLinks.forEach(link => {
958	                    link.addEventListener('click', closeMenu);
959	                });
960	            }
961	
962	            const learnMoreBtn = document.getElementById('learn-more-btn');
963	            if (learnMoreBtn) {
964	                learnMoreBtn.addEventListener('click', function() {
965	                    const getStartedSection = document.getElementById('get-started');
966	                    if (getStartedSection) {
967	                        getStartedSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
968	                        document.getElementById('name').focus();
969	                    }
970	                });
971	            }
972	
973	            const contactForm = document.getElementById('contact-form');
974	            if (contactForm) {
975	                const showError = (field, message) => {
976	                    const fieldGroup = field.closest('.form-group');
977	                    const error = fieldGroup.querySelector('.field-error');
978	                    if (error) {
979	                        error.classList.add('show');
980	                        error.textContent = message;
981	                    }
982	                    field.setAttribute('aria-invalid', 'true');
983	                };
984	
985	                const clearError = (field) => {
986	                    const fieldGroup = field.closest('.form-group');
987	                    const error = fieldGroup.querySelector('.field-error');
988	                    if (error) {
989	                        error.classList.remove('show');
990	                        error.textContent = '';
991	                    }
992	                    field.setAttribute('aria-invalid', 'false');
993	                };
994	
995	                const validateField = (field) => {
996	                    const value = field.value.trim();
997	
998	                    if (!value) {
999	                        showError(field, `${field.labels?.[0]?.textContent || 'This field'} is required`);
1000	                        return false;
1001	                    }
1002	
1003	                    if (!field.checkValidity()) {
1004	                        let message = 'Invalid input';
1005	                        if (field.type === 'email') {
1006	                            message = 'Please enter a valid email address (e.g., name@domain.com)';
1007	                        } else if (field.id === 'name') {
1008	                            if (field.value.length < 2) {
1009	                                message = 'Name must be at least 2 characters long';
1010	                            } else {
1011	                                message = 'Name can only contain letters and spaces';
1012	                            }
1013	                        } else if (field.id === 'message') {
1014	                            if (field.value.length < 10) {
1015	                                message = `Message must be at least 10 characters (currently ${field.value.length})`;
1016	                            } else if (field.value.length > 1000) {
1017	                                message = `Message cannot exceed 1000 characters (currently ${field.value.length})`;
1018	                            } else {
1019	                                message = 'Please provide a valid message';
1020	                            }
1021	                        }
1022	                        showError(field, message);
1023	                        return false;
1024	                    }
1025	
1026	                    clearError(field);
1027	                    return true;
1028	                };
1029	
1030	                const messageField = document.getElementById('message');
1031	                const messageCounter = document.getElementById('message-counter');
1032	
1033	                const updateMessageCounter = () => {
1034	                    if (messageCounter) {
1035	                        messageCounter.textContent = `${messageField.value.length} / 1000`;
1036	                    }
1037	                };
1038	
1039	                if (messageField && messageCounter) {
1040	                    updateMessageCounter();
1041	                    messageField.addEventListener('input', updateMessageCounter);
1042	                }
1043	
1044	                const inputs = contactForm.querySelectorAll('input, textarea');
1045	                inputs.forEach(input => {
1046	                    input.addEventListener('blur', () => validateField(input));
1047	                });
1048	
1049	                let isSubmitting = false;
1050	
1051	                contactForm.addEventListener('submit', function(e) {
1052	                    e.preventDefault();
1053	
1054	                    if (isSubmitting) return;
1055	
1056	                    let isValid = true;
1057	                    const feedback = document.getElementById('form-feedback');
1058	                    feedback.className = 'form-feedback';
1059	                    feedback.textContent = '';
1060	
1061	                    inputs.forEach(input => {
1062	                        if (!validateField(input)) isValid = false;
1063	                    });
1064	
1065	                    if (!isValid) {
1066	                        feedback.className = 'form-feedback error';
1067	                        feedback.textContent = 'Please correct the errors above and try again.';
1068	                        setTimeout(() => feedback.focus(), 100);
1069	                        return;
1070	                    }
1071	
1072	                    const submitBtn = document.getElementById('submit-btn');
1073	                    isSubmitting = true;
1074	                    submitBtn.disabled = true;
1075	                    submitBtn.classList.add('loading');
1076	                    const originalHTML = submitBtn.innerHTML;
1077	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
1078	                    submitBtn.innerHTML = '<span class="spinner" aria-hidden="true"></span>Sending...';
1079	                    submitBtn.setAttribute('aria-label', 'Sending message, please wait');
1080	
1081	                    const formData = new FormData(contactForm);
1082	                    const endpoint = contactForm.getAttribute('data-endpoint') || '/contact';
1083	                    const controller = new AbortController();
1084	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
1085	
1086	                    fetch(endpoint, {
1087	                        method: 'POST',
1088	                        body: formData,
1089	                        signal: controller.signal
1090	                    })
1091	                    .then(response => {
1092	                        if (response.ok) {
1093	                            feedback.className = 'form-feedback success';
1094	                            feedback.textContent = 'Thank you for your message! We will be in touch soon.';
1095	                            contactForm.reset();
1096	                            inputs.forEach(input => {
1097	                                clearError(input);
1098	                            });
1099	                            updateMessageCounter();
1100	                        } else {
1101	                            throw new Error(`Server error: ${response.status}`);
1102	                        }
1103	                    })
1104	                    .catch(error => {
1105	                        feedback.className = 'form-feedback error';
1106	                        if (error.name === 'AbortError') {
1107	                            feedback.textContent = 'Request timed out. Please try again.';
1108	                        } else if (error instanceof TypeError) {
1109	                            feedback.textContent = 'Network error. Please check your connection and try again.';
1110	                        } else {
1111	                            feedback.textContent = 'Something went wrong. Please try again later.';
1112	                        }
1113	                    })
1114	                    .finally(() => {
1115	                        clearTimeout(timeoutId);
1116	                        isSubmitting = false;
1117	                        submitBtn.disabled = false;
1118	                        submitBtn.classList.remove('loading');
1119	                        submitBtn.innerHTML = originalHTML;
1120	                        if (originalAriaLabel) {
1121	                            submitBtn.setAttribute('aria-label', originalAriaLabel);
1122	                        }
1123	                        setTimeout(() => {
1124	                            feedback.scrollIntoView({ behavior: 'smooth', block: 'center' });
1125	                            feedback.focus();
1126	                        }, 100);
1127	                    });
1128	                });
1129	            }
1130	        });
1131	    </script>
1132	</body>
