fetch(endpoint, {
    method: 'POST',
    body: formData,
    signal: controller.signal
})
.then(response => {
    if (response.ok) {
        feedback.className = 'form-feedback success';
        feedback.textContent = 'Thank you for your message! We will be in touch soon.';
        contactForm.reset();
        inputs.forEach(input => {
            clearError(input);
        });
        updateMessageCounter();
    } else {
        throw new Error(`Server error: ${response.status}`);
    }
})
.catch(error => {
    feedback.className = 'form-feedback error';
    if (error.name === 'AbortError') {
        feedback.textContent = 'Request timed out. Please try again.';
    } else if (error instanceof TypeError) {
        feedback.textContent = 'Network error. Please check your connection and try again.';
    } else {
        feedback.textContent = 'Something went wrong. Please try again later.';
    }
})

