input.old_string:
const validateField = (field) => {
    const value = field.value.trim();

    if (!value) {
        showError(field, `${field.labels?.[0]?.textContent || 'This field'} is required`);
        return false;
    }

    if (!field.checkValidity()) {
        let message = 'Invalid input';
        if (field.type === 'email') {
            message = 'Please enter a valid email address (e.g., name@domain.com)';
        } else if (field.id === 'name') {
            if (field.value.length < 2) {
                message = 'Name must be at least 2 characters long';
            } else {
                message = 'Name can only contain letters and spaces';
            }
        } else if (field.id === 'message') {
            if (field.value.length < 10) {
                message = `Message must be at least 10 characters (currently ${field.value.length})`;
            } else if (field.value.length > 1000) {
                message = `Message cannot exceed 1000 characters (currently ${field.value.length})`;
            } else {
                message = 'Please provide a valid message';
            }
        }
        showError(field, message);
        return false;
    }

    clearError(field);
    return true;
};

